func TestEnumAgentStatus(t *testing.T) {
	t.Run("NewFromString_active", func(t *testing.T) {
		t.Parallel()
		val, err := NewAgentStatusFromString("active")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AgentStatus("active"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_deleting", func(t *testing.T) {
		t.Parallel()
		val, err := NewAgentStatusFromString("deleting")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AgentStatus("deleting"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_deletion_failed", func(t *testing.T) {
		t.Parallel()
		val, err := NewAgentStatusFromString("deletion_failed")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AgentStatus("deletion_failed"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewAgentStatusFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewAgentStatusFromString("active")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

func TestExtraPropertiesAgent(t *testing.T) {
	t.Run("GetExtraProperties", func(t *testing.T) {
		t.Parallel()
		obj := &Agent{}
		// Should not panic when calling GetExtraProperties()
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("GetExtraProperties() panicked: %v", r)
			}
		}()
		extraProps := obj.GetExtraProperties()
		// Result can be nil or an empty/non-empty map
		_ = extraProps
	})

	t.Run("GetExtraProperties_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *Agent
		extraProps := obj.GetExtraProperties()
		assert.Nil(t, extraProps, "nil receiver should return nil without panicking")
	})
}

